INSERT OR REPLACE INTO recipes (slug, json, updated_at) VALUES ('tabbouleh', '{"slug":"tabbouleh","title":"Tabbouleh","description":"Middle Eastern herb and bulgur salad — zingy, fragrant, and so refreshing. Perfect for a mezze platter or picnic!","tags":["Salads"],"servings":"6","prepTime":"20 min","cookTime":"20 min","image":"","ingredients":["⅓ cup extra-virgin olive oil","3 tbsp fresh lemon juice","1 garlic clove, grated","½ tsp sea salt","¼ tsp ground coriander","Pinch cinnamon","3 cups finely chopped curly parsley (about 2 bunches)","1 cup diced English cucumber","1 cup cored and diced tomato","⅔ cup cooked bulgur wheat","⅓ cup finely chopped fresh mint","2 scallions, chopped"],"steps":["Whisk together olive oil, lemon juice, garlic, salt, coriander, and cinnamon in a large bowl.","Add parsley, cucumber, tomato, bulgur, mint, and scallions; toss to combine.","Season to taste and chill until serving."],"notes":"Coarse bulgur: boil 2 cups water, add 1 cup dry bulgur, cover, and remove from heat. Let sit 20 to 30 minutes until tender, then drain excess water and fluff with a fork; use ⅔ cup cooked bulgur, cooled before adding. Fine bulgur: place in a bowl, cover with ½ inch water, and soak 20 minutes until tender, then drain.","source":{"url":"https://www.loveandlemons.com/tabbouleh/","name":"Love and Lemons"},"updatedAt":"2026-10-20T12:00:00Z"}', '2026-10-20T12:00:00Z');
